+
+      // The one-line reason a FlatBars diagnostic panel is absent under MinBars.
+      // A panel drops off automatically once MinBars advertises its backing
+      // capability (so this self-maintains as engine seams land). Panels not listed
+      // here (Problems/Performance/Coverage/Syntax Tree) are always present.
+      const MINBARS_ABSENT_REASONS = {
+        "data-access": "needs the lowered AST — the Mustache engine exposes none yet",
+        "partials": "needs the lowered AST (the partial dependency graph)",
+        "truthiness": "a MinBars truthiness analysis — planned",
+        "lint": "Mustache has no deprecated aliases or scoped variables to canonicalize",
+        "context": "needs an output→source map MinBars doesn't emit",
+      };
+
+      // MinBars is a logic-less engine without the lowered-AST / source-map seams the
+      // FlatBars panels read. Rather than silently showing fewer tabs, surface a
+      // "Why fewer panels?" popover listing each absent panel and its reason.
+      function paintWhyFewerPanels(strip) {
+        if (ENGINE !== "minbars") return;
+        const absent = dockTabs.filter((t) => MINBARS_ABSENT_REASONS[t.id] && !tabVisible(t));
+        if (!absent.length) return;
+        const det = makeEl("details", { class: "dock-why" });
+        det.append(
+          makeEl("summary", {}, "Why fewer panels?"),
+          makeEl("div", { class: "dock-why-body" }, [
+            makeEl("p", {}, "MinBars renders Mustache — a logic-less engine without the lowered-AST / source-map seams the FlatBars diagnostic panels read:"),
+            makeEl("ul", {}, absent.map((t) =>
+              makeEl("li", {}, [ makeEl("b", {}, t.label), " — " + MINBARS_ABSENT_REASONS[t.id] ]))),
+          ]),
+        );
+        strip.append(det);
       }

